// Original Rucking Revolution editorial content. Example schedules, not entry standards.
const p=(title,text)=>({title,text});
const l=(title,items)=>({title,items});
const discussion=(label,url,note)=>[{label,url,note},{label:'Wayback capture index — '+label,url:'https://web.archive.org/web/*/'+url,note:'Search for past captures; individual snapshots and comments have not been verified.'}];
const pathfinder={label:'Petersen, A. (2026, January 5). How PATHFINDER training works. PATHFINDER Ruck Training.',url:'https://pathfinderrucktraining.com/blogs/pathfinder-ruck-training-the-blog/how-pathfinder-training-works',note:'Public overview of an independent commercial training approach; these plans are original and are not its paid materials.'};
const review={label:'Orr, R., Pope, R., Lopes, T. J. A., Leyk, D., Blacker, S., Sanz Bustillo-Aguirre, B., & Knapik, J. J. (2021). Soldier load carriage, injuries, rehabilitation and physical conditioning: An international approach. International Journal of Environmental Research and Public Health, 18(8), 4010.',url:'https://doi.org/10.3390/ijerph18084010',note:'Background reading on load carriage, strength, aerobic work and progression; military workloads are not civilian prescriptions.'};
const pfThread=discussion('Community discussion: Training','https://www.reddit.com/r/Goruck/comments/1fl00as','Participants discuss how gym training and event-specific work fit together. Personal views, not universal advice.');
const backThread=discussion('Community discussion: back-to-back long days','https://www.reddit.com/r/ultrarunning/comments/1ae1u6f/','Runners discuss benefits and drawbacks; running experiences do not directly prescribe loaded walking.');
const plans=[
 {slug:'first-twelve-weeks-ruck-plan',title:'Your first 12 weeks of rucking',level:'Beginner',summary:'Build a routine you can keep. Start with short walks and finish with a longer outing if you are ready.',meta:'12 weeks · 3 training days · beginner',start:'Start here if you can walk for 20–30 minutes comfortably without a pack. Use no added weight or a light, familiar load. If that walk is not comfortable, begin with shorter walks and repeat the first week as needed.',rhythm:'Tuesday: easy walk or ruck. Thursday: strength (20–25 minutes). Saturday: longer easy outing. Rest or walk gently on the other days. For strength, use 2 sets of 6–10 sit-to-stands, hinges, low step-ups, wall or incline push-ups and light carries; stop with a few repetitions left.',weeks:['1: Tue 20 min; Sat 30 min; learn pack fit.','2: Tue 25 min; Sat 35 min; same load.','3: Tue 25 min; Sat 40 min; try a familiar loop.','4: Tue 20 min; Sat 30 min; easier week.','5: Tue 30 min; Sat 45 min; keep the pace conversational.','6: Tue 30 min; Sat 50 min; practise a drink stop.','7: Tue 35 min; Sat 55 min; keep load unchanged.','8: Tue 25 min; Sat 40 min; easier week.','9: Tue 35 min; Sat 60 min; include a gentle hill if comfortable, or stay flat.','10: Tue 40 min; Sat 65 min; check footwear.','11: Tue 40 min; Sat 75 min; rehearse a familiar snack and route.','12: Tue 25 min; Sat 60–75 min at your own pace; compare how it feels with week 1.'],finish:'If any week leaves you sore enough to change your walking, repeat or shorten it. Do not chase the calendar. Add pack weight only after the current routine feels comfortably repeatable, and shorten the outing when trying a heavier load.'},
 {slug:'twelve-week-distance-ruck-plan',title:'12 weeks to a longer ruck',level:'Intermediate',summary:'For regular ruckers working toward a comfortable 20–30 km walk or a first longer event.',meta:'12 weeks · 4 training days · distance',start:'Start only if you already complete a 90-minute familiar-load ruck comfortably and recover by the next day. The weekend times are examples; distance depends on your pace, terrain and stops.',rhythm:'Tuesday: 35–50 minutes easy. Thursday: 25–35 minutes strength (2–3 sets of 6–10 squats, hinges, step-ups, rows and carries). Friday or Wednesday: 20–35 minutes easy cycling or walking. Weekend: the outing below. Avoid hard leg training just before it.',weeks:['1: 90 min; record pace, stops and comfort.','2: 105 min; keep weight and terrain familiar.','3: 120 min; practise food and water.','4: 75–90 min; easier week.','5: 135 min; choose a route with exit points.','6: 150 min; use planned refill stops.','7: 165 min; keep the same load.','8: 105 min; easier week.','9: 180 min; rehearse event kit only if already familiar.','10: 195 min; practise pacing the second half.','11: 120–150 min; reduce workload and check recovery.','12: Target outing at a sustainable effort; if needed choose a shorter finish, not a forced distance.'],finish:'If your planned event requires substantially more time than your longest comfortable outing, extend this programme with repeatable training blocks rather than making one large jump. A finish target is optional; neither 20 nor 30 km is guaranteed.'},
 {slug:'twelve-week-hill-ruck-plan',title:'12 weeks for hills and mountain days',level:'Intermediate',summary:'Develop climbing strength, controlled descents and longer outings without relying on a heavier pack.',meta:'12 weeks · 4 training days · hills',start:'For people already comfortable with a 60–90 minute walk on mixed terrain. Choose a modest hill with safe footing and an easy return. Keep the pack light enough for controlled steps.',rhythm:'Tuesday: hill session below, plus 10 minutes easy warm-up and cool-down. Thursday: 2–3 sets of 6–10 step-ups, split squats, hinges and rows, with easy calf raises. Saturday: longer walk. One optional easy unloaded aerobic day, at least one full rest day.',weeks:['1: 4 × 2 min uphill; 60 min weekend.','2: 5 × 2 min uphill; 65 min weekend.','3: 5 × 2 min uphill; 80 min weekend.','4: 3 × 2 min uphill; 55–60 min easy.','5: 5 × 3 min uphill; 80 min weekend.','6: 6 × 3 min uphill; 80 min weekend.','7: 6 × 3 min uphill; 100 min weekend.','8: 4 × 2 min uphill; 65 min easy.','9: 5 × 4 min uphill; 100 min weekend.','10: 5 × 4 min uphill; 120 min weekend.','11: 4 × 3 min uphill; 75 min weekend.','12: Easy midweek walk; choose a familiar hill route for a 90–120 min outing if recovered.'],finish:'Walk downhill slowly between repeats, allowing breathing to settle. If the longer outing includes substantial climbing, cut the weekday hill work. Progress slope, pace or time separately. Do not train on exposed or icy terrain to meet a schedule.'},
 {slug:'eight-week-team-endurance-plan',title:'Eight weeks for a team endurance challenge',level:'Advanced',summary:'Combine repeatable rucks, shared carries, practical communication and strength without trying to recreate an extreme event.',meta:'8 weeks · 4 training days · team',start:'For regular ruckers already comfortable with a 90–120 minute outing and basic strength work. Choose a partner or group that can agree on individual load, rest and withdrawal. No sleep deprivation, forced carries or punishment workouts.',rhythm:'Tuesday: 35–45 min easy ruck. Thursday: 30–40 min strength, using 2–3 sets of 6–10 squats, hinges, rows and controlled carries. Weekend: group session. One optional easy walk/cycle day; keep the day after group work easy.',weeks:['1: 75–90 min group outing; plan roles and check-ins.','2: 90 min; include 4 × 60 s shared carries with unloaded recovery.','3: 105 min; rehearse a route change and food stop.','4: 60–75 min; no demanding carries.','5: 120 min; include 4 × 90 s carry rotations, if week 2 was comfortable.','6: 135 min; keep shared carry volume unchanged; practise role handovers.','7: 75–90 min easy; reduce total work.','8: Chosen group challenge within established capacity; brief alternatives and finish together at a safe pace.'],finish:'The group should learn to share work, not compete over who suffers most. Make every session adjustable. An actual event may require different preparation or more time; read its rules before choosing a target.'}
];
const planRows=plans.map(x=>[x.slug,x.title,x.level,x.summary,x.meta,[p('Who this is for',x.start),p('A normal training week',x.rhythm),l('Week by week',x.weeks),p('How to adjust',x.finish)],{updated:'2026-11-24',trainingPlan:true,sources:[pathfinder,review,...(x.slug.includes('team')?pfThread:[])]}]);
const article=(slug,title,summary,blocks,sources=[])=>[slug,title,'All',summary,'Training · practical guide',blocks,{updated:'2026-11-24',...(sources.length?{sources}: {})}];
export const intensityArticle=article('intensity-drives-adaptation','Intensity drives adaptation','Harder work has a place. The trick is knowing what needs to be harder, and when.',[
 p('The same hill, a different day','There is a hill you know well. You know where the road steepens, where it flattens briefly, and roughly how far you have to go before you can stop thinking about the climb. A few months ago you had to slow down halfway up. Now you walk it without much fuss. That is progress. The question is what you do with it.'),
 p('Hard is not always the same thing','You could put more weight in your pack. You could keep the weight and walk a little faster, or climb the hill twice. All three make the outing harder, but they do not ask the same thing of you. If you struggle on steep ground, adding another five kilos on a flat road might not address the problem. If your shoulders give out before your legs, sprinting every hill may not be the answer either.'),
 p('Make the work count','For endurance, sometimes the useful change is another half hour at a pace you can hold. For climbing, it might be four controlled uphill efforts, with enough time on the way down to do the next one properly. For strength, it might be a heavier squat in the gym, where you can put the weight down when the set is done. There is no prize for making all three harder on the same day.'),
 p('The work after the work','A hard session is an invitation for your body to adapt, not a guarantee that it will. Food, sleep and the time between demanding sessions matter. If Saturday leaves you dragging yourself through Tuesday, perhaps Saturday was too much. Some weeks the best decision is to repeat the last one. A session you can build on is worth more than one you spend a fortnight recovering from.'),
 p('Keep a little record','Write down the route, load, time and what it felt like. How did the last third compare with the first? How did your legs feel the following morning? Next time, change one thing. It will not always be obvious that you are getting fitter, but a few months of ordinary notes can show you what the mirror and the scale cannot.'),
 p('Go back to the hill','The easy days still belong in the plan. They give you room to practise, enjoy the walk and come back ready for a harder one. Intensity drives certain adaptations; the quieter work builds the base that lets you use that intensity. The hill will still be there next week. You do not have to settle the argument with it today.')]);
export const newTrainingArticles=[intensityArticle,...planRows,
 article('training-with-a-limited-week','Make training fit a busy week','Keep useful work when the calendar gets crowded.',[p('Choose the essentials','For a distance goal, keep a comfortable long outing and one shorter session. For a strength goal, keep two short strength sessions. Put them in the calendar first.'),p('A three-day version','Tuesday: 30 minutes steady. Thursday: 25 minutes strength. Saturday: 60 minutes or your normal comfortable long outing. Shorten rather than double up when a day disappears.'),p('A two-day version','One 30–40 minute strength or mixed session and one comfortable longer outing. If time is tight, a 15-minute walk is still useful. Do not try to squeeze the entire missing week into Saturday.'),p('Review on Sunday','Check what actually happened, including work stress and sleep. Start the next week where you are, not where the old plan said you should be.')],[pathfinder,...pfThread]),
 article('back-to-back-days-without-the-crash','Back-to-back days without the crash','Learn how to start a second day without turning every weekend into a survival exercise.',[p('Why do it at all?','A second day can teach you about overnight recovery, foot care and pacing. It is most relevant when your goal involves more than one day on foot.'),p('Start small','If your normal long ruck is 90 minutes, try 60–75 minutes on Saturday and an easy unloaded 20–30 minute walk on Sunday. Keep the combined workload close to what you already handle.'),p('The morning check','Before leaving, check feet, ordinary walking, sleep and appetite. Shorten or skip the second day if you are limping or unusually exhausted. A missed training day is a small cost compared with an injury.'),p('Make it useful','Use the second day to practise sorting kit, refilling water, drying socks and adjusting the plan. Increase either the first or second day only after comfortable recovery. Do not turn two days into two maximal efforts.')],backThread),
 article('how-to-train-for-carrying','Train to carry, not just to walk','Build the strength and confidence to move a pack or shared object without losing control.',[p('What a pack does not train','A backpack is predictable. A sandbag changes shape, a handle can tire your grip, and a team carry requires coordination. Strength work helps fill those gaps.'),p('A simple session','Two or three rounds: 6–8 controlled squats, 6–8 hinges, 8 rows and a 20–30 m carry. Rest 60–120 seconds or longer. Choose a weight you can put down safely.'),p('Practise the handover','With a partner, practise a short carry and exchange on level ground. Say when you need to stop, put the object down together, and never try to catch a falling load.'),p('Progress without drama','Extend a carry or increase resistance in one movement, not everything together. Keep a clear area and do not add a pack to an unfamiliar lift.')]),
 article('practice-event-logistics','Rehearse the boring parts of an adventure','Food, footwear, timing and small decisions can shape an entire day.',[p('Build a little dress rehearsal','Choose a route within your established capacity. Wear your intended socks, pack and layers. Use the food you expect to take and check whether you can reach it without emptying the pack.'),p('Make a plan for stops','Note refill points, toilets, transport and the latest time you can turn back. Tell someone where you are going and when you expect to return.'),p('Try one problem at a time','Take a planned detour, change a layer before you get cold, or practise changing a sock. Do this in a safe place, not by manufacturing a hazardous emergency.'),p('Record the annoyances','Which pocket was difficult to reach? Did you eat before you ran out of energy? What would you leave at home next time, provided it is not mandatory equipment?')]),
 article('build-a-personal-challenge-calendar','Build your own challenge calendar','A few well-chosen challenges can give ordinary training direction.',[p('Pick one main goal','Choose something meaningful and realistic for your current level: a local 15 km walk, two days of trekking or a team outing. Read the actual requirements.'),p('Use stepping stones','Choose a smaller challenge roughly every four weeks: a longer loop, a route with hills, a pack-fit outing or a shared carry practice. Substitute it for the normal hard session.'),p('Keep the calendar flexible','If you miss a challenge, do not stack it onto the next weekend. A change in weather, work or recovery is a good reason to move it.'),p('Look back before choosing more','After the goal, write down what you learnt. Leave room for easier weeks and decide whether the next goal is more distance, better speed, new terrain or simply sharing the experience.')]),
 article('training-when-progress-stalls','When your rucking progress stalls','Use a familiar route to work out what is holding you back.',[p('Look for the actual bottleneck','On a familiar route with the same load, notice whether breathing, climbing, pack discomfort or general tiredness is making you slow down.'),p('Give yourself a fair comparison','Use similar conditions and record elapsed time, moving time, stops, terrain and effort. Wind, snow and a heavier pack can explain a slower outing.'),p('Choose one experiment','If hills are the problem, try short controlled climbs. If the pack rubs, adjust the setup on a short outing. If you are tired from work or other training, make a week easier.'),p('Check again','Repeat the route after a few weeks without turning it into a race. If pain, numbness or a change in normal walking is part of the problem, stop and get appropriate advice rather than increasing training.')])];
const w=(slug,title,level,summary,minutes,purpose,equipment,dose,steps,progress)=>[slug,title,level,summary,`${minutes} min · ${purpose.toLowerCase()}`,[l('Session',steps),p('Progress',progress),p('Working dose',dose+'. Adjust to your usual capacity.')],{minutes,purpose,equipment,dose}];
export const newTrainingWorkouts=[
 w('controlled-uphill-repeats','Controlled uphill repeats','Intermediate','Practise a strong uphill pace without racing the descent.',40,'Endurance',['Pack'],'4–6 × 2 min uphill; walk down to recover',['Warm up 10 minutes on an easy route.','Walk uphill briskly for 2 minutes with a familiar light pack. Walk down slowly and wait until breathing settles.','Repeat 4 times, then cool down. Add up to 2 repeats only if form and recovery are good.'],'Add a repeat or a little time; keep load unchanged.'),
 w('pack-off-strength-circuit','Pack-off strength circuit','Beginner','Build useful leg and upper-body strength without wearing your pack through every exercise.',30,'Strength',['Bodyweight','Weights'],'2–3 sets of 6–10 repetitions; 60–120 s rest',['Warm up with easy walking and unloaded movements.','Do a squat or sit-to-stand, hinge, step-up, row and incline push-up in controlled sets.','Rest between sets; finish with a short light carry if comfortable.'],'Add repetitions first or resistance to one movement, leaving a few repetitions in reserve.'),
 w('steady-pace-change','Steady ruck with pace changes','Intermediate','Learn to change pace and return to an easy effort.',45,'Endurance',['Pack'],'5 × 3 min brisk / 3 min easy',['Walk easily for 8 minutes.','Alternate 3 minutes brisk and 3 minutes easy, 5 times, on a safe level route.','Cool down for 7 minutes. Keep the brisk pace controlled, not a loaded run.'],'Repeat at the same load; increase brisk time only when recovery stays comfortable.'),
 w('short-team-handover','Short team handover practice','All','Practise communicating and sharing an awkward load.',35,'Teamwork',['Group','Sandbag'],'4–6 × 60 s shared carry; easy recovery',['Agree a manageable object and a clear level route.','Walk 5–10 minutes to warm up. Carry for 60 seconds, put it down together and switch roles.','Walk unloaded until ready for the next round. Finish with a brief review of communication and load choices.'],'Add one round or change roles, not the weight and duration together.')];
export const originalPlanSlugs=plans.map(x=>x.slug);
